WITH matched_keys AS (SELECT account_id, id FROM transactions EXCEPT ALL SELECT account_id, id FROM transactions WHERE account_id IN (18, 20, 27)), reconciled AS (SELECT s.* FROM transactions s INNER JOIN matched_keys k ON s.account_id = k.account_id AND s.id = k.id) SELECT s.account_id, s.txn_type, s.amount, s.txn_time, s.is_flagged, (SELECT SUM(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS sum_transaction_amount FROM reconciled s ORDER BY sum_transaction_amount DESC, amount
